from itertools import combinations, product


def _build_route(exact, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        initial_mask = required_bit.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, 0)
        distances = {start_state: data["start"]}
        queue = [(data["start"], *start_state)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if (node == data["target"] and mask == full
                    and (not exact or used == data["coupons"])):
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [edge["duration"]]
                if used < data["coupons"]:
                    durations.append(max(minimum_duration,
                                         edge["duration"] - edge.get("discount", 0)))
                for choice, duration in enumerate(durations):
                    next_used = used + (1 if choice else 0)
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, *next_state))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {}
        for name in names:
            rows_by_name[name] = [row for row in packages[name]
                                  if row["version"] not in blocked.get(name, [])
                                  and (name not in pins or row["version"] == pins[name])]

        best = None
        best_vector = None
        # None represents an absent package; otherwise select one available row.
        choices = [[None] + rows_by_name[name] for name in names]
        for assignment in product(*choices):
            selected = {name: row for name, row in zip(names, assignment)
                        if row is not None}
            valid = True
            for name, bounds in roots.items():
                row = selected.get(name)
                if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            graph = {name: [] for name in selected}
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = selected.get(dep["name"])
                    if (target is None or
                            not dep["min"] <= target["version"] <= dep["max"]):
                        valid = False
                        break
                    graph[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            # Every installed package must be in the active closure of a root.
            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                if name in graph:
                    pending.extend(graph[name])
            if reachable != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(child) for child in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in graph):
                continue

            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best = {name: row["version"] for name, row in selected.items()}

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_08():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for selected in combinations(options, k):
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in selected)
            selected_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value
                    or (value == best_value and selected_ids > best_ids)):
                best_value = value
                best_ids = selected_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


